const bool enabled = args()[0].GetBool();
if (profile()->IsOffTheRecord() && enabled) {
  return RespondNow(
      Error("Private profiles cannot remain active in background"));
}
auto runtime = std::make_unique<KeepTasksRuntime>();
if (enabled) {
  runtime->keep_alive = std::make_unique<ScopedKeepAlive>(
      KeepAliveOrigin::BACKGROUND_MODE_MANAGER,
      KeepAliveRestartOption::DISABLED);
}
profile()->SetUserData(kKeepTasksRuntimeKey, std::move(runtime));
prefs->SetBoolean(kKeepTasks, enabled);

